// ============================================================
//  cube.ts — Geometria de um cubo unitário (dados na CPU)
// ------------------------------------------------------------
//  Cubo unitário centrado na origem (de -0.5 a 0.5 em cada eixo).
//  É a geometria BASE reutilizada por INSTANCING: desenhamos este
//  mesmo cubo N vezes, cada instância com sua matriz model e cor
//  (ver Renderer + storage buffer).
//
//  Cada vértice: posição (x,y,z) + "shade" (1 float).
//  O shade é um brilho fixo POR FACE, embutido nos dados. Ele NÃO
//  é iluminação de verdade (isso é a FASE 15) — serve só para dar
//  contraste entre as faces e o mapa ficar legível em 3D:
//    topo = 1.0 | frente/trás = 0.75 | laterais = 0.6 | base = 0.45
//
//  36 vértices (6 faces × 2 triângulos × 3), não-indexado. O winding
//  é anti-horário visto de fora, casando com cullMode:"back".
// ============================================================

export const CUBE_FLOATS_PER_VERTEX = 4; // x, y, z, shade

const T = 1.0; // topo
const F = 0.75; // frente/trás
const S = 0.6; // laterais
const B = 0.45; // base

// prettier-ignore
export const CUBE_VERTICES = new Float32Array([
  // ---- face traseira (-z) ----
  -0.5, -0.5, -0.5, F,   0.5,  0.5, -0.5, F,   0.5, -0.5, -0.5, F,
  -0.5, -0.5, -0.5, F,  -0.5,  0.5, -0.5, F,   0.5,  0.5, -0.5, F,
  // ---- face frontal (+z) ----
  -0.5, -0.5,  0.5, F,   0.5, -0.5,  0.5, F,   0.5,  0.5,  0.5, F,
  -0.5, -0.5,  0.5, F,   0.5,  0.5,  0.5, F,  -0.5,  0.5,  0.5, F,
  // ---- face esquerda (-x) ----
  -0.5, -0.5, -0.5, S,  -0.5, -0.5,  0.5, S,  -0.5,  0.5,  0.5, S,
  -0.5, -0.5, -0.5, S,  -0.5,  0.5,  0.5, S,  -0.5,  0.5, -0.5, S,
  // ---- face direita (+x) ----
   0.5, -0.5, -0.5, S,   0.5,  0.5, -0.5, S,   0.5,  0.5,  0.5, S,
   0.5, -0.5, -0.5, S,   0.5,  0.5,  0.5, S,   0.5, -0.5,  0.5, S,
  // ---- face inferior (-y) ----
  -0.5, -0.5, -0.5, B,   0.5, -0.5, -0.5, B,   0.5, -0.5,  0.5, B,
  -0.5, -0.5, -0.5, B,   0.5, -0.5,  0.5, B,  -0.5, -0.5,  0.5, B,
  // ---- face superior (+y) ----
  -0.5,  0.5, -0.5, T,  -0.5,  0.5,  0.5, T,   0.5,  0.5,  0.5, T,
  -0.5,  0.5, -0.5, T,   0.5,  0.5,  0.5, T,   0.5,  0.5, -0.5, T,
]);

export const CUBE_VERTEX_COUNT = CUBE_VERTICES.length / CUBE_FLOATS_PER_VERTEX; // 36

